SELECT DISTINCT cs.canonical_smiles, sub_cr.compound_name AS substrate_compound_name, md.pref_name AS parent_compound_name, m.met_conversion, m.pathway_key, m.organism, m.enzyme_name FROM metabolism m JOIN compound_records sub_cr ON m.substrate_record_id = sub_cr.record_id JOIN molecule_dictionary sub_md ON sub_cr.molregno = sub_md.molregno LEFT JOIN compound_structures cs ON sub_md.molregno = cs.molregno LEFT JOIN molecule_dictionary md ON m.parent_molregno = md.molregno WHERE m.enzyme_name = 'CYP1A2' ORDER BY cs.canonical_smiles, sub_cr.compound_name, md.pref_name, m.met_conversion, m.pathway_key, m.organism, m.enzyme_name LIMIT 200
